method incr_list(l: seq<int>) returns (result: seq<int>)
    requires l != null
    ensures |result| == |l| && forall i :: 0 <= i < |l| ==> result[i] == l[i] + 1
{
    var n := |l|;
    result := new int[n];
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant |result| == n
        invariant forall j :: 0 <= j < i ==> result[j] == l[j] + 1
    {
        result[i] := l[i] + 1;
        i := i + 1;
    }
}

